package com.silverroom.camera;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.io.*;import java.util.*;

/** All calls belong to the film worker. No negative is moved, recompressed or renamed by migration. */
final class RollRepository extends SQLiteOpenHelper {
    static final String MOBILE="phone",HISTORY="history",METER="meter";
    private final File negatives;
    RollRepository(Context c,File dir){super(c,"fancy-archive.db",null,1);negatives=dir;}
    @Override public void onCreate(SQLiteDatabase db){for(String sql:ArchiveSchema.CREATE)db.execSQL(sql);}
    @Override public void onUpgrade(SQLiteDatabase db,int old,int next){for(String sql:ArchiveSchema.CREATE)db.execSQL(sql);}
    static JSONObject json(String value){try{return new JSONObject(value);}catch(Exception e){return new JSONObject();}}
    static JSONObject copy(JSONObject value){return json(value==null?"{}":value.toString());}
    static JSONObject object(Object... pairs){JSONObject j=new JSONObject();for(int i=0;i+1<pairs.length;i+=2)try{Object v=pairs[i+1];if(v instanceof Double&&!Double.isFinite((Double)v)||v instanceof Float&&!Float.isFinite((Float)v))continue;j.put(String.valueOf(pairs[i]),v);}catch(JSONException ignored){}return j;}
    private void defaultRoll(SQLiteDatabase db,String id,String name,String kind){ContentValues v=new ContentValues();v.put("id",id);v.put("name",name);v.put("kind",kind);v.put("created",0);v.put("data",object("stock",1,"nominal_iso",400,"capacity",0,"process","","camera","","lens","").toString());db.insertWithOnConflict("rolls",null,v,SQLiteDatabase.CONFLICT_IGNORE);}
    synchronized void syncLegacy()throws IOException{
        SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{
            defaultRoll(db,MOBILE,"手机随拍","phone");defaultRoll(db,HISTORY,"历史底片","phone");defaultRoll(db,METER,"实体拍摄记录","physical");
            for(String id:NegativeStore.list(negatives)){if(!new File(negatives,id+".jpg").isFile()||!new File(negatives,id+"_original.jpg").isFile())continue;JSONObject metadata=readMeta(id);if(find("items",id)==null){String roll=metadata.optString("archive_roll",HISTORY);if(find("rolls",roll)==null)roll=HISTORY;photo(id,roll,metadata.optString("archive_snapshot","{}"),metadata,metadata.has("parent_id"));}}
            db.setTransactionSuccessful();
        }finally{db.endTransaction();}
    }
    JSONObject readMeta(String id){if(!NegativeStore.valid(id))return new JSONObject();try{return json(new String(java.nio.file.Files.readAllBytes(new File(negatives,id+".json").toPath()),java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){return new JSONObject();}}
    synchronized JSONObject find(String table,String id){if(!Arrays.asList("rolls","items","equipment","film_profiles").contains(table))throw new IllegalArgumentException("Invalid archive table");try(Cursor c=getReadableDatabase().query(table,null,"id=?",new String[]{id},null,null,null)){if(!c.moveToFirst())return null;return row(c);}}
    private JSONObject row(Cursor c){JSONObject j=json(c.getString(c.getColumnIndexOrThrow("data")));for(String field:c.getColumnNames())if(!field.equals("data"))try{int i=c.getColumnIndexOrThrow(field);j.put(field,c.getType(i)==Cursor.FIELD_TYPE_INTEGER?c.getLong(i):c.getString(i));}catch(JSONException ignored){}return j;}
    synchronized List<JSONObject> list(String table,String kind){if(!Arrays.asList("rolls","equipment","film_profiles").contains(table))throw new IllegalArgumentException("Invalid archive table");String order=table.equals("rolls")?"pinned DESC, rank ASC, created DESC":"name COLLATE NOCASE";List<JSONObject> result=new ArrayList<>();try(Cursor c=getReadableDatabase().query(table,null,kind==null?null:"kind=?",kind==null?null:new String[]{kind},null,null,order)){while(c.moveToNext())result.add(row(c));}return result;}
    synchronized void saveRoll(JSONObject j){String id=j.optString("id",UUID.randomUUID().toString());ContentValues v=new ContentValues();v.put("id",id);v.put("name",j.optString("name","未命名胶卷"));v.put("kind",j.optString("kind","phone"));v.put("status",Math.max(0,Math.min(3,j.optInt("status",0))));v.put("pinned",j.optBoolean("pinned",false)||j.optInt("pinned",0)==1?1:0);v.put("rank",j.optInt("rank",0));v.put("created",j.optLong("created",System.currentTimeMillis()));v.put("data",j.toString());getWritableDatabase().insertWithOnConflict("rolls",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    synchronized void saveProfile(String table,JSONObject j){if(!table.equals("equipment")&&!table.equals("film_profiles"))throw new IllegalArgumentException("Invalid profile table");ContentValues v=new ContentValues();v.put("id",j.optString("id",UUID.randomUUID().toString()));v.put("name",j.optString("name","自定义"));if(table.equals("equipment"))v.put("kind",j.optString("kind","camera"));v.put("data",j.toString());getWritableDatabase().insertWithOnConflict(table,null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    synchronized void deleteProfile(String table,String id){if(!table.equals("equipment")&&!table.equals("film_profiles"))throw new IllegalArgumentException("Invalid profile table");getWritableDatabase().delete(table,"id=?",new String[]{id});}
    synchronized List<JSONObject> items(String roll){List<JSONObject> result=new ArrayList<>();try(Cursor c=getReadableDatabase().query("items",null,roll==null?null:"roll_id=?",roll==null?null:new String[]{roll},null,null,"created DESC,id DESC")){while(c.moveToNext()){JSONObject j=row(c);if(j.optLong("deleted_at",0)>0)continue;String id=j.optString("id");if(j.optString("kind").equals("meter")||new File(negatives,id+".json").isFile()&&new File(negatives,id+".jpg").isFile())result.add(j);}}return result;}
    synchronized int count(String roll){int count=0;for(JSONObject i:items(roll))count+=i.optInt("exposure_count",1);return count;}
    synchronized void photo(String id,String roll,String snapshot,JSONObject metadata,boolean derivative){if(!NegativeStore.valid(id))throw new IllegalArgumentException("Invalid photo ID");JSONObject data=copy(metadata);try{data.put("roll_snapshot",json(snapshot));}catch(JSONException ignored){}putItem(id,roll,metadata.optBoolean("imported",false)?"import":"photo",metadata.optLong("captured_at",ArchiveSchema.photoTime(id,System.currentTimeMillis())),derivative?0:1,data);}
    synchronized String meter(String roll,JSONObject data){String id="meter-"+UUID.randomUUID();putItem(id,roll,"meter",System.currentTimeMillis(),1,data);return id;}
    private void putItem(String id,String roll,String kind,long created,int exposureCount,JSONObject data){if(find("rolls",roll)==null)roll=kind.equals("meter")?METER:MOBILE;JSONObject old=find("items",id);if(old!=null&&old.has("annotations"))try{data.put("annotations",old.getJSONObject("annotations"));}catch(JSONException ignored){}ContentValues v=new ContentValues();v.put("id",id);v.put("roll_id",roll);v.put("kind",kind);v.put("created",created);v.put("exposure_count",exposureCount);v.put("data",data.toString());getWritableDatabase().insertWithOnConflict("items",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    synchronized void annotate(String id,JSONObject annotations){JSONObject item=find("items",id);if(item==null)return;try{item.put("annotations",annotations);ContentValues v=new ContentValues();v.put("data",item.toString());getWritableDatabase().update("items",v,"id=?",new String[]{id});}catch(JSONException ignored){}}
    synchronized void move(List<String> ids,String target){if(find("rolls",target)==null)throw new IllegalArgumentException("胶卷不存在");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("roll_id",target);for(String id:ids)db.update("items",v,"id=?",new String[]{id});db.setTransactionSuccessful();}finally{db.endTransaction();}}
    synchronized void removeRoll(String id){if(id.equals(MOBILE)||id.equals(HISTORY)||id.equals(METER))throw new IllegalArgumentException("默认归档不可删除");SQLiteDatabase db=getWritableDatabase();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("roll_id",HISTORY);db.update("items",v,"roll_id=?",new String[]{id});db.delete("rolls","id=?",new String[]{id});db.setTransactionSuccessful();}finally{db.endTransaction();}}
    synchronized void removeMeter(String id){JSONObject item=find("items",id);if(item!=null&&item.optString("kind").equals("meter")){try{item.put("deleted_at",System.currentTimeMillis());}catch(JSONException ignored){}ContentValues v=new ContentValues();v.put("data",item.toString());getWritableDatabase().update("items",v,"id=?",new String[]{id});}}
    synchronized void reference(String id,String filename){JSONObject item=find("items",id);if(item==null||!item.optString("kind").equals("meter"))return;try{item.put("reference",filename);ContentValues v=new ContentValues();v.put("data",item.toString());getWritableDatabase().update("items",v,"id=?",new String[]{id});}catch(JSONException ignored){}}
    synchronized List<JSONObject> meterTrash(){List<JSONObject> rows=new ArrayList<>();try(Cursor c=getReadableDatabase().query("items",null,"kind=?",new String[]{"meter"},null,null,"created DESC")){while(c.moveToNext()){JSONObject j=row(c);long date=j.optLong("deleted_at",0);if(date>0){if(System.currentTimeMillis()-date>NegativeTrash.RETENTION)getWritableDatabase().delete("items","id=?",new String[]{j.optString("id")});else rows.add(j);}}}return rows;}
    synchronized void restoreMeter(String id){JSONObject item=find("items",id);if(item==null)return;item.remove("deleted_at");ContentValues v=new ContentValues();v.put("data",item.toString());getWritableDatabase().update("items",v,"id=?",new String[]{id});}
    synchronized String csv(String roll){
        StringBuilder out=new StringBuilder("\ufeff类型,编号,胶卷,拍摄日期,实际相机,实际镜头,实际ISO,实际光圈,实际快门秒,EV100,备注,参数来源,补填相机,补填镜头,补填ISO,补填光圈,补填快门秒,补填日期,实体EI,实体建议光圈,实体建议快门秒,ND档,迫冲档\r\n");
        for(JSONObject i:items(roll)){
            JSONObject actual=i.optJSONObject("capture"),notes=i.optJSONObject("annotations"),snap=i.optJSONObject("roll_snapshot");
            if(actual==null)actual=i.optJSONObject("source_capture");if(actual==null)actual=new JSONObject();if(notes==null)notes=new JSONObject();if(snap==null)snap=new JSONObject();boolean meter=i.optString("kind").equals("meter");
            JSONObject associated=find("rolls",i.optString("roll_id"));String currentName=associated==null?i.optString("roll_id"):associated.optString("name");String camera=(actual.optString("make")+" "+actual.optString("model")).trim();
            String[] fields={i.optString("kind"),i.optString("id"),currentName,i.optString("source_datetime",i.has("captured_at")?String.valueOf(i.optLong("captured_at")):""),camera,actual.optString("focal_mm",""),actual.optString("iso",""),actual.optString("aperture",""),actual.has("exposure_ns")?String.valueOf(actual.optLong("exposure_ns")/1e9):"",i.optString("ev100",""),notes.optString("notes",i.optString("notes","")),i.has("capture")?"手机实际参数":meter?"实体相机建议":"原始EXIF与独立补填",notes.optString("camera"),notes.optString("lens"),notes.optString("iso"),notes.optString("aperture"),notes.optString("seconds"),notes.optString("date"),meter?i.optString("ei"):"",meter?i.optString("aperture"):"",meter?i.optString("seconds"):"",meter?i.optString("nd"):"",meter?i.optString("push"):""};
            for(int n=0;n<fields.length;n++)out.append(n==0?"":",").append(ArchiveSchema.csv(fields[n]));out.append("\r\n");
        }return out.toString();
    }
}
